-- Copy to Sheets: triggers for leaders (generated by setup/build-mirror-sql.mjs; see 0022 for the design).
CREATE TRIGGER mirror_leaders_ins AFTER INSERT ON leaders BEGIN INSERT INTO mirror_log (tbl, k1, k2) VALUES ('leaders', NEW."login", ''); END;
CREATE TRIGGER mirror_leaders_upd AFTER UPDATE ON leaders BEGIN INSERT INTO mirror_log (tbl, k1, k2) VALUES ('leaders', NEW."login", ''); END;
CREATE TRIGGER mirror_leaders_key AFTER UPDATE ON leaders WHEN OLD."login" IS NOT NEW."login" BEGIN INSERT INTO mirror_log (tbl, k1, k2) VALUES ('leaders', OLD."login", ''); END;
CREATE TRIGGER mirror_leaders_del AFTER DELETE ON leaders BEGIN INSERT INTO mirror_log (tbl, k1, k2) VALUES ('leaders', OLD."login", ''); END;
INSERT OR IGNORE INTO mirror_state (tbl, mode) VALUES ('leaders', 'build');
UPDATE mirror_state SET mode = 'build', last_id = 0, rows = 0, gen = 0, cursor = '' WHERE tbl = 'leaders';
